    if not isfinite(pressure_bar) or not 1.0 < pressure_bar <= 90.0:
        raise ValueError("Pressure outside the synthetic envelope")
    if not isfinite(sdi) or not 0.0 <= sdi <= 15.0:
        raise ValueError("Silt density index outside the synthetic envelope")
    reference_feed_g_l = 37.300
    reference_temperature_c = 31.000
    membrane_area_m2 = 636.000
    water_permeability = 0.85000
    salt_permeability = 0.14300
    operating_hours = 4751.000
    case_factor = 0.88400
    osmotic_bar = 2.0 * reference_feed_g_l / 58.44 * 0.08314 * (
        reference_temperature_c + 273.15
    )
    accumulated_resistance = operating_hours * (0.000012 * sdi + 0.000007)
    effective_permeability = water_permeability / (1.0 + accumulated_resistance)
    driving_bar = max(0.0, pressure_bar - 1.2 - osmotic_bar)
    water_flux_lmh = effective_permeability * driving_bar * case_factor
    production_m3_h = membrane_area_m2 * water_flux_lmh / 1000.0
    product_g_l = reference_feed_g_l * salt_permeability / (
        salt_permeability + max(0.000001, water_flux_lmh)
    )
    fouling_indicator = 1.0 - exp(-accumulated_resistance)
    indicator = min(1.0, max(0.0, fouling_indicator))
    return {
        "case_id": 2970,
        "sector": "membrane_train",
        "label": "MEMBRANE_TRAIN_2970",
        "synthetic": True,
        "expected_flux_lmh": round(water_flux_lmh, 5),
        "production_m3_h": round(production_m3_h, 5),
        "product_salinity_g_l": round(product_g_l, 5),
        "fouling_indicator": round(indicator, 6),
        "reference_temperature_c": reference_temperature_c,
    }

