def evaluate_case(case_id: int, pressure_bar: float, sdi: float) -> dict[str, object]:
    return SCENARIOS[case_id](pressure_bar, sdi)

def case_index(limit: int) -> list[dict[str, object]]:
    if not 1 <= limit <= 100:
        raise ValueError("Index limit must be between 1 and 100")
    return [
        {"case_id": number, "sector": SCENARIOS[number](62.0, 3.0)["sector"]}
        for number in range(1, limit + 1)
    ]
